// TASK-0037 — V1 Change Journal on Manual Refresh, product acceptance in real
// WebView2. No simulated DOM, no alternate renderer, no personal data: the
// tree under test was generated by task0037-seed-proof.py (plus a batch this
// script writes) and dies with the proof root.
//
// Two phases, one REAL process restart between them (run by the .ps1):
//
//   phase 1  first index -> empty journal; create, modify, rename, move,
//            delete — each performed by THIS script directly on disk,
//            outside the product process, between two real `Actualiser`
//            clicks — asserting the exact counters and the same nodeId at
//            every step; then a 130-file batch for a >50-event history,
//            filtered and paginated through the real panel.
//   phase 2  after the real restart: the very same history is still there.
//
// Reuses the TASK-0033..0036 harness technique (REAL_ROOT registered
// directly into a fresh sandbox catalogue, the real product driven through
// CDP) rather than building a second framework.
import assert from "node:assert/strict";
import { readFile, writeFile, rename, rm, mkdir } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
const phase = Number(process.argv[4]);
assert(/^task0037-[a-f0-9]+$/.test(variant));
assert(phase === 1 || phase === 2);

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const { brainId, absolutePath } = seed;
const proofRoot = join(".filetopo-sandbox", variant);
const root = absolutePath; // real absolute path, used only by THIS script's own fs calls — never sent into the page.

let target;
for (let n = 0; n < 100; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(200);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) {
    throw new Error(
      r.exceptionDetails.exception?.description ??
        r.exceptionDetails.exception?.value ??
        JSON.stringify(r.exceptionDetails),
    );
  }
  return r.result.value;
}
async function until(expression, limit = 240000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
const exposedPayloads = [];
const invoke = async (command, args = {}) => {
  exposedPayloads.push(JSON.stringify(args));
  const result = await evaluate(
    `window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`,
  );
  exposedPayloads.push(JSON.stringify(result ?? null));
  return result;
};
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");

async function key(k) {
  const vk = k === "Enter" ? 13 : 0;
  await send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: k,
    code: k,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk,
    ...(k === "Enter" ? { text: "\r", unmodifiedText: "\r" } : {}),
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", key: k, code: k, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
  await pause(120);
}
async function activate(selector) {
  const found = await evaluate(`!!document.querySelector(${JSON.stringify(selector)})`);
  assert(found, `activate: selector not found — ${selector}`);
  await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);
  await key("Enter");
}
const jargon = [
  "stable_key",
  "stableKey",
  "identity_provenance",
  "identityProvenance",
  "SYS1:",
  "PFv1:",
  "PATH_FALLBACK",
  "fileId",
  "file_id",
  "volumeSerial",
  "volume_serial",
];
function assertNoJargon(text, where) {
  for (const word of jargon) assert(!text.includes(word), `internal identity jargon "${word}" leaked into ${where}`);
}
const escaped = root.split("\\").join("\\\\");
function assertNoPathLeak(text, where) {
  assert(!text.includes(root) && !text.includes(escaped), `absolute path leaked into ${where}`);
}

async function waitForAppReady() {
  await until(`!!document.querySelector('[data-testid="details-panel-toggle"]')`);
  await until(`!!document.querySelector('[data-testid="change-journal"]')`);
  await until(`document.querySelector('[data-testid="lifecycle-open"]') && !document.querySelector('[data-testid="lifecycle-open"]').disabled`);
}
const revisionExpression = `(() => { const t = document.querySelector('[data-testid="report-brain"]')?.textContent ?? ''; const m = /révision (\\d+)/.exec(t); return m ? Number(m[1]) : -1; })()`;
const currentRevision = () => evaluate(revisionExpression);
/** One real Actualiser click; resolves with the counters the UI shows for it. */
async function refreshAndSummarize() {
  const before = await currentRevision();
  await activate('[data-testid="lifecycle-refresh"]');
  await until(`${revisionExpression} > ${before}`);
  await until(`!document.querySelector('[data-testid="lifecycle-open"]').disabled`);
  await pause(300);
  const raw = await evaluate(
    `document.querySelector('[data-testid="change-summary"]')?.getAttribute('data-summary') ?? 'null'`,
  );
  const summary = JSON.parse(raw);
  assert(summary, "the report must show the change counters after Actualiser");
  return summary;
}
function assertCounters(summary, expected, where) {
  const actual = {
    created: summary.created,
    modified: summary.modified,
    renamed: summary.renamed,
    moved: summary.moved,
    deleted: summary.deleted,
    total: summary.total,
  };
  assert.deepEqual(actual, { created: 0, modified: 0, renamed: 0, moved: 0, deleted: 0, total: 0, ...expected }, where);
}
async function resolve(relativePath) {
  const reference = await invoke("map_resolve_node", { brainId, relativePath });
  assert(reference, `no node resolves at ${relativePath}`);
  return reference.nodeId;
}

// ---- the real panel ---------------------------------------------------------
async function openJournal() {
  const open = await evaluate(`document.querySelector('[data-testid="journal-toggle"]').getAttribute('aria-expanded') === 'true'`);
  if (!open) await activate('[data-testid="journal-toggle"]');
  await until(`!!document.querySelector('[data-testid="journal-total"]')`);
}
async function setFilters(natures) {
  for (const nature of ["CREATED", "MODIFIED", "RENAMED", "MOVED", "DELETED"]) {
    const checked = await evaluate(`document.querySelector('[data-testid="journal-filter-${nature}"]').checked`);
    if (checked !== natures.includes(nature)) {
      await evaluate(`document.querySelector('[data-testid="journal-filter-${nature}"]').click()`);
    }
  }
  await pause(200);
}
/** What the panel shows right now, once it has settled on `total`. */
async function panelState(total) {
  await until(
    `(() => { const e = document.querySelector('[data-testid="journal-total"]'); return !!e && Number(e.getAttribute('data-total')) === ${total}; })()`,
  );
  await pause(200);
  return evaluate(`(() => {
    const total = document.querySelector('[data-testid="journal-total"]');
    const events = [...document.querySelectorAll('[data-testid="journal-event"]')];
    return {
      total: Number(total.getAttribute('data-total')),
      limit: Number(total.getAttribute('data-limit')),
      events: events.map((e) => ({
        eventId: Number(e.getAttribute('data-event-id')),
        nature: e.getAttribute('data-nature'),
        nodeId: Number(e.getAttribute('data-node-id')),
        present: e.getAttribute('data-node-present') === 'true',
        hasSelect: !!e.querySelector('[data-testid="journal-select"]'),
        text: e.textContent,
      })),
      nextDisabled: document.querySelector('[data-testid="journal-next"]').disabled,
      prevDisabled: document.querySelector('[data-testid="journal-prev"]').disabled,
    };
  })()`);
}
/** Walks every page through the real « Page suivante » button. */
async function walkAllPages(total) {
  let state = await panelState(total);
  const pages = [state];
  while (!state.nextDisabled) {
    const firstId = state.events[0].eventId;
    await activate('[data-testid="journal-next"]');
    await until(
      `(() => { const e = document.querySelector('[data-testid="journal-event"]'); return !!e && Number(e.getAttribute('data-event-id')) !== ${firstId}; })()`,
    );
    await pause(200);
    state = await panelState(total);
    pages.push(state);
    assert(pages.length < 20, "runaway pagination");
  }
  return pages;
}
async function backToFirstPage() {
  for (let n = 0; n < 10; n++) {
    const disabled = await evaluate(`document.querySelector('[data-testid="journal-prev"]').disabled`);
    if (disabled) return;
    await activate('[data-testid="journal-prev"]');
    await pause(300);
  }
}

const results = {};
await waitForAppReady();

if (phase === 1) {
  // ---- 1 — first index: baseline, empty journal ---------------------------
  const first = await refreshAndSummarize();
  assert.equal(first.baselineEstablished, true, "a first build establishes the baseline");
  assertCounters(first, {}, "first build counters");
  results.firstBuildBaseline = true;
  await openJournal();
  const empty = await panelState(0);
  results.firstBuildJournalEmpty = empty.total === 0 && empty.events.length === 0;
  assert(results.firstBuildJournalEmpty);
  const overview = await invoke("map_open", { brainId });
  results.schemaVersion = overview.schemaVersion;
  assert.equal(overview.schemaVersion, 5, "the product runs on the v5 schema");

  // ---- 2 — an unchanged Actualiser is quiet -------------------------------
  const quiet = await refreshAndSummarize();
  assert.equal(quiet.baselineEstablished, false);
  assertCounters(quiet, {}, "no-op refresh counters");
  results.unchangedRefreshZeroEvents = true;

  // ---- 3 — CREATED ---------------------------------------------------------
  await writeFile(join(root, "nouveau.txt"), "synthetique — objet cree\n", "utf8");
  const created = await refreshAndSummarize();
  assertCounters(created, { created: 1, total: 1 }, "create counters");
  const createdId = await resolve("nouveau.txt");
  let state = await panelState(1);
  results.createdEvent =
    state.events.length === 1 && state.events[0].nature === "CREATED" && state.events[0].nodeId === createdId;
  assert(results.createdEvent, "one CREATED event on the new node");

  // ---- 4 — MODIFIED --------------------------------------------------------
  await writeFile(join(root, "a-modifier.txt"), "synthetique — apres, plus long qu'avant\n", "utf8");
  const modifiedSummary = await refreshAndSummarize();
  assertCounters(modifiedSummary, { modified: 1, total: 1 }, "modify counters");
  const modifiedId = await resolve("a-modifier.txt");
  state = await panelState(2);
  results.modifiedEvent = state.events[0].nature === "MODIFIED" && state.events[0].nodeId === modifiedId;
  assert(results.modifiedEvent);

  // ---- 5 — RENAMED: same nodeId -------------------------------------------
  const renameIdBefore = await resolve("a-renommer.txt");
  await rename(join(root, "a-renommer.txt"), join(root, "renomme.txt"));
  const renamedSummary = await refreshAndSummarize();
  assertCounters(renamedSummary, { renamed: 1, total: 1 }, "rename counters (no delete/create)");
  const renameIdAfter = await resolve("renomme.txt");
  results.renameKeepsNodeId = renameIdAfter === renameIdBefore;
  state = await panelState(3);
  results.renamedEvent = state.events[0].nature === "RENAMED" && state.events[0].nodeId === renameIdBefore;
  assert(results.renameKeepsNodeId && results.renamedEvent);

  // ---- 6 — MOVED: same nodeId ---------------------------------------------
  const moveIdBefore = await resolve("a-deplacer.txt");
  await rename(join(root, "a-deplacer.txt"), join(root, "destination", "a-deplacer.txt"));
  const movedSummary = await refreshAndSummarize();
  assertCounters(movedSummary, { moved: 1, total: 1 }, "move counters (no delete/create)");
  const moveIdAfter = await resolve("destination/a-deplacer.txt");
  results.moveKeepsNodeId = moveIdAfter === moveIdBefore;
  state = await panelState(4);
  results.movedEvent = state.events[0].nature === "MOVED" && state.events[0].nodeId === moveIdBefore;
  assert(results.moveKeepsNodeId && results.movedEvent);

  // ---- 7 — DELETED ---------------------------------------------------------
  const deletedId = await resolve("a-supprimer.txt");
  await rm(join(root, "a-supprimer.txt"));
  const deletedSummary = await refreshAndSummarize();
  assertCounters(deletedSummary, { deleted: 1, total: 1 }, "delete counters");
  state = await panelState(5);
  const deletedEvent = state.events[0];
  results.deletedEvent = deletedEvent.nature === "DELETED" && deletedEvent.nodeId === deletedId;
  results.deletedOffersNoSelection = deletedEvent.present === false && deletedEvent.hasSelect === false;
  assert(results.deletedEvent && results.deletedOffersNoSelection, "a DELETED event is history only");

  // ---- 8 — a >50-event history: filters and pagination ---------------------
  await mkdir(join(root, "lot"), { recursive: true });
  for (let n = 0; n < 130; n++) {
    await writeFile(join(root, "lot", `lot-${String(n).padStart(3, "0")}.txt`), `synthetique ${n}\n`, "utf8");
  }
  const batchSummary = await refreshAndSummarize();
  assertCounters(batchSummary, { created: 130, total: 130 }, "batch counters");
  results.batchCounters = { created: batchSummary.created, total: batchSummary.total };

  const TOTAL = 135;
  const pages = await walkAllPages(TOTAL);
  const seenIds = pages.flatMap((p) => p.events.map((e) => e.eventId));
  results.paginationPageSizes = pages.map((p) => p.events.length);
  results.paginationNoGapNoDuplicate =
    seenIds.length === TOTAL &&
    new Set(seenIds).size === TOTAL &&
    seenIds.every((id, i) => i === 0 || seenIds[i - 1] > id);
  assert.deepEqual(results.paginationPageSizes, [50, 50, 35], "pages of at most 50");
  assert(results.paginationNoGapNoDuplicate, "no event lost or repeated across pages");
  assert(pages.every((p) => p.limit === 50 && p.total === TOTAL));
  await backToFirstPage();
  const firstPageAfterBack = await panelState(TOTAL);
  results.pageBackRestoresFirstPage =
    JSON.stringify(firstPageAfterBack.events.map((e) => e.eventId)) ===
    JSON.stringify(pages[0].events.map((e) => e.eventId));
  assert(results.pageBackRestoresFirstPage);

  // Filters: visible, combinable, revocable, with an exact total.
  await setFilters(["CREATED"]);
  const createdOnly = await panelState(131);
  results.filterCreatedTotal = createdOnly.total;
  await setFilters(["RENAMED", "MOVED"]);
  const renamedMoved = await panelState(2);
  results.filterRenamedMovedTotal = renamedMoved.total;
  assert(renamedMoved.events.every((e) => e.nature === "RENAMED" || e.nature === "MOVED"));
  await setFilters(["DELETED"]);
  const deletedOnly = await panelState(1);
  results.filterDeletedTotal = deletedOnly.total;
  assert(deletedOnly.events.every((e) => !e.hasSelect && !e.present));
  await setFilters(["MODIFIED"]);
  results.filterModifiedTotal = (await panelState(1)).total;
  await setFilters([]);
  const revoked = await panelState(TOTAL);
  results.filtersRevocable = revoked.total === TOTAL;
  assert(results.filtersRevocable);

  // ---- 9 — select a live node through the journal --------------------------
  await setFilters(["MOVED"]);
  const movedOnly = await panelState(1);
  assert(movedOnly.events[0].hasSelect, "a live node offers a selection");
  await activate('[data-testid="journal-select"]');
  await until(`(document.querySelector('.details')?.textContent ?? '').includes('a-deplacer.txt')`);
  results.selectFromJournalShowsTheNode = true;
  await setFilters([]);

  // ---- 10 — API bounds ---------------------------------------------------------
  const apiFirst = await invoke("map_change_journal", { brainId, natures: [], after: null, limit: 500 });
  results.apiPageIsBounded = apiFirst.items.length === 50 && apiFirst.limit === 50 && apiFirst.total === TOTAL;
  assert(results.apiPageIsBounded, "the API never returns more than 50 events");
  const apiSecond = await invoke("map_change_journal", { brainId, natures: [], after: apiFirst.nextCursor, limit: 50 });
  results.apiCursorContinues = apiSecond.items.length === 50 && apiSecond.items[0].eventId < apiFirst.items[49].eventId;
  assert(results.apiCursorContinues);

  // ---- persist what phase 2 must find again ---------------------------------
  results.snapshot = {
    total: TOTAL,
    firstPageEventIds: pages[0].events.map((e) => e.eventId),
    lastPageEventIds: pages[2].events.map((e) => e.eventId),
    createdTotal: 131,
    deletedNodeId: deletedId,
  };
  results.indexedNodeCount = (await invoke("map_view", { brainId })).nodeCount;

  // ---- confidentiality ------------------------------------------------------
  const bodyText = await evaluate("document.body.textContent");
  assertNoPathLeak(bodyText, "page body text");
  assertNoJargon(bodyText, "page body text");
  for (const payload of exposedPayloads) {
    assertNoPathLeak(payload, "an invoke payload");
    assertNoJargon(payload, "an invoke payload");
  }
  results.noAbsolutePathOrIdentityLeak = true;
} else {
  // ---- phase 2: after a REAL process restart ---------------------------------
  const before = JSON.parse(await readFile(join(proofRoot, "phase1.json"), "utf8"));
  const snapshot = before.snapshot;
  await until(`${revisionExpression} >= 0`);
  await openJournal();
  const TOTAL = snapshot.total;
  const pages = await walkAllPages(TOTAL);
  const seenIds = pages.flatMap((p) => p.events.map((e) => e.eventId));
  results.historyTotalAfterRestart = pages[0].total;
  results.historyTotalSurvives = pages[0].total === TOTAL;
  results.firstPageIdenticalAfterRestart =
    JSON.stringify(pages[0].events.map((e) => e.eventId)) === JSON.stringify(snapshot.firstPageEventIds);
  results.lastPageIdenticalAfterRestart =
    JSON.stringify(pages[pages.length - 1].events.map((e) => e.eventId)) ===
    JSON.stringify(snapshot.lastPageEventIds);
  results.paginationNoGapNoDuplicateAfterRestart = seenIds.length === TOTAL && new Set(seenIds).size === TOTAL;
  assert(results.historyTotalSurvives, `history total ${pages[0].total} != ${TOTAL}`);
  assert(results.firstPageIdenticalAfterRestart, "the newest page is unchanged after the restart");
  assert(results.lastPageIdenticalAfterRestart, "the oldest page is unchanged after the restart");
  assert(results.paginationNoGapNoDuplicateAfterRestart);

  // All five natures are still there, and the deleted node is still history only.
  const natures = new Set(pages.flatMap((p) => p.events.map((e) => e.nature)));
  results.allFiveNaturesSurvive = ["CREATED", "MODIFIED", "RENAMED", "MOVED", "DELETED"].every((n) => natures.has(n));
  assert(results.allFiveNaturesSurvive);
  await setFilters(["DELETED"]);
  const deleted = await panelState(1);
  results.deletedStillHistoryOnly =
    deleted.events[0].nodeId === snapshot.deletedNodeId && !deleted.events[0].present && !deleted.events[0].hasSelect;
  assert(results.deletedStillHistoryOnly);
  await setFilters([]);

  // A restart must not have re-scanned anything: opening is not a refresh.
  const overview = await invoke("map_open", { brainId });
  results.openAfterRestartReadNoSource = overview.sourceRead === false;
  results.schemaVersion = overview.schemaVersion;
  assert(results.openAfterRestartReadNoSource && overview.schemaVersion === 5);

  const bodyText = await evaluate("document.body.textContent");
  assertNoPathLeak(bodyText, "page body text");
  assertNoJargon(bodyText, "page body text");
  for (const payload of exposedPayloads) {
    assertNoPathLeak(payload, "an invoke payload");
    assertNoJargon(payload, "an invoke payload");
  }
  results.noAbsolutePathOrIdentityLeak = true;
}

await writeFile(join(proofRoot, `phase${phase}.json`), JSON.stringify(results));
console.log(JSON.stringify({ ok: true, phase }));

assert.equal(fatal.length, 0, `fatal page/console errors`);
await writeFile(join(proofRoot, `phase${phase}-fatal-count.json`), JSON.stringify(fatal.length));
ws.close();
